; text_demo_sd.asm - generated by gen_text_demo_sd.py, do not edit
;
; THE SD CARD BUILD (TEXT.PLC): text_demo.asm with the pages it uses
; moved into RAM 0100-1EFF 2000-3AFF (page map: 60>24 62>25 63>26 64>27 66>28 67>29 68>2A 6A>2B 6B>2C 6C>2D 6D>2E 6E>2F 6F>30 70>31 71>32 72>33 73>34 74>35 75>36 76>37 80>20 81>21 82>22 83>23 90>16 91>17 92>18 93>19 94>1A 95>1B 96>1C 97>38 98>01 99>02 9A>03 9B>04 9C>05 9D>06 9E>07 9F>08 A0>09 A1>0A A2>0B A3>1D A4>1E A5>39 A6>3A A7>0C A8>0D A9>0E AA>0F AB>10 AC>11 AD>12 AE>13 AF>14 B0>15),
; and the RAM test on the free RAM only: 3B00-4CFF 5400-59FF 5C00-5CFF.
;
; text_demo.asm - text and color demo drawn by the CPU, with a live RAM test
;
; Draws a screen that uses all four color depths and the line repeat modes,
; then keeps running and shows it on the screen:
;
;   rows   0-95   1 bpp, 1x   80 column text (2 colors): title, the whole
;                             character set (normal and inverse), the live
;                             status lines, a column ruler and a legend.
;                             Row tints (mode byte bits 6:4, VIDEO.md "Row
;                             tint"): the status lines sit on a blue panel
;                             and a rainbow raster bar bounces up and down
;                             behind the text, moved only by mode bytes
;   rows  96-223  4 bpp, 4x   16 colors (160 x 32): "16 COLORS" in big
;                             letters, the 16 color bars and a spinning wheel
;   rows 224-351  2 bpp, 2x   40 column text (320 x 64), 8 rows of 8 x 16
;                             characters in the 4 colors, with a message
;                             scrolling a pixel a frame on the bottom row
;   rows 352-479  8 bpp, 4x   256 colors (80 x 32): "256" in big digits, the
;                             2 in shades of red, the 5 in blues and the 6 in
;                             greens, and a turning rainbow ring
;
; The bands are placed so no two rows share a video byte (docs/video/VIDEO.md, line
; repeat): 1x rows 0-95 use offsets x020-x07F of each byte column, 4x rows
; 96-223 x181 + 4n, 2x rows 224-351 the odd offsets x101-x17F and 4x rows
; 352-479 x183 + 4n.
;
; While it runs, once per frame (frame_poll):
;   - RAM test: one 256-byte page per frame of x0100-x1EFF, x2000-x4FFF,
;     x5400-x59FF and x5C00-x5CFF (85 pages, 21.25 KB: all of the RAM below
;     the video but the zero page, LIB_RAM at x1F00, the I/O window, the
;     mode bytes and the audio buffer), 14 patterns each (00, FF, 55, AA,
;     walking 1, and the address XOR a seed and its complement), write then
;     read back.  The progress bar fills a block per two pages (an inverse
;     E marks a pair with errors); PASS counts full passes and ERRORS counts
;     failed checks (a pattern that read back wrong on a page).
;   - the raster bar, first, while the video is in vertical blanking: the
;     20 mode bytes it covered get their panel tint back (TINTB) and the
;     20 at its new place get the bar (BARP, place from BARY)
;   - the frame counter, the uptime clock (60 frames = 1 s), the text
;     spinner, the 16-color wheel (one step every 3 frames), the scrolling
;     message (one pixel a frame) and the 256-color ring (a step a frame).
;   The busiest frame is about 182,000 clocks in placard_sim.
;
; It is a ROM program (docs/architecture/ROM.md): it runs in place from ROM x6000-xAFFF,
; uses the standard library (docs/software/LIBRARY.md) and the zero page map, and
; keeps its variables in the zero page x20-x8E.  It doesn't use the ROM at
; x2000-x3FFF, so it sets map 07 (section 1 reads RAM) to test that RAM too.
;
;     python3 gen_text_demo_tables.py         (writes text_demo_tables.asm)
;     python3 placard_sim.py text_demo.asm --run --max-steps 3000000 --png td.png
;     python3 text_demo_sim.py                (checks it; --gif for an animation)
;
; Date: 10/22/2026

#include "placard.asm"
#include "placard_lib.asm"

; ---------------------------------------------------------------------------
; program variables (zero page x20-x8F)
; ---------------------------------------------------------------------------
last_frame = 0x20       ; FRAME_LO when the last frame was handled
spin_div   = 0x21       ; frames until the text spinner steps
spin_ph    = 0x22       ; text spinner phase 0-3
big_div    = 0x23       ; frames until the wheel steps
big_ph     = 0x24       ; wheel phase 0-7 (the bright dot)
sec_div    = 0x25       ; frames until the next second
scr_q      = 0x26       ; scroller: pixel 0-7 in the first character
marq_lo    = 0x27       ;   the message character in CH + 0
marq_hi    = 0x28
CLK        = 0x29       ; uptime "hhmmss", 6 ASCII digits x29-x2E
FRM        = 0x2F       ; frame count, 5 ASCII digits x2F-x33
rt_idx     = 0x34       ; RAM test: page number 0-84 in the pass
rt_page    = 0x35       ;   page address high byte
rt_pat     = 0x36       ;   pattern 0-13
wh_ph      = 0x37       ; 256-color ring: rainbow phase
rt_pv      = 0x38       ; RAM test: pattern value
rt_bad     = 0x39       ;   1 when this page pair had an error
pass_lo    = 0x3A       ;   passes done
pass_hi    = 0x3B
err_lo     = 0x3C       ;   failed checks
err_hi     = 0x3D
rt_i       = 0x3E       ;   byte in the page (X is not a source)
dg_i       = 0x3F       ; td_tick_frames / td_tick_clock: digit being stepped

p_col      = 0x40       ; td_fill_run / td_put_gbuf / td_rect: first byte column
p_n        = 0x41       ;   bytes across
p_rlo      = 0x42       ;   screen row 0-479
p_rhi      = 0x43
p_val      = 0x44       ;   fill byte
p_hi       = 0x45       ;   (working address high byte)
p_rows     = 0x46       ;   td_rect: rows to fill
p_step     = 0x47       ;   td_rect: row step (the line repeat: 1, 2 or 4)
p_cnt      = 0x48       ;   (working count)
gb0        = 0x49       ; td_put_gbuf bytes 0-3
gb1        = 0x4A
gb2        = 0x4B
gb3        = 0x4C
c_ch       = 0x4D       ; td_char2 / td_char4: character
c_col      = 0x4E       ;   text column 0-39 (char2) or byte column (char4)
c_row      = 0x4F       ;   text row 0-7 (char2) or block row 0-31 (char4)
c_fr       = 0x50       ;   (font row)
c_fg       = 0x51       ;   foreground fill XOR background fill
c_bg       = 0x52       ;   background fill
c_i        = 0x53       ; td_puts4: character number
s_attr     = 0x54       ; td_put_str / td_put_range: OR mask (80 = inverse)
tp_lo      = 0x55       ; td_tbl_next: table pointer
tp_hi      = 0x56
tb_v       = 0x57
i0         = 0x58       ; loop counters
i1         = 0x59
pz_n       = 0x5A       ; td_print_zp: count
pr_c       = 0x5B       ; td_put_range: character
pr_n       = 0x5C       ;   count
pr_inc     = 0x5D       ;   0 = repeat, 1 = count up
dot_k      = 0x5E       ; wheel dot 0-7
CH         = 0x5F       ; scroller: the 41 message characters on screen,
                        ;   x5F-x87
wh_k       = 0x88       ; 256-color ring: pixel
wh_t       = 0x89       ;   its color
wh_x       = 0x8A       ;   its row offset
tn_ph      = 0x8B       ; raster bar: phase (a step every 2 frames)
tn_pos     = 0x8C       ;   x20 + its first row now (mode byte low address)
tn_i       = 0x8D       ;   (row in the bar)
tn_v       = 0x8E       ;   (its mode byte)
TN_N       = 20         ;   rows in the bar

; td_scroll's working bytes share the drawing routines' bytes (x49-x53, x58),
; which are only used while the screen is drawn
sc_vy      = 0x49       ; video page of the even byte column
sc_vo      = 0x4A       ;   of the odd byte column
sc_vx      = 0x4B       ;   row offset of the font row
sc_f0      = 0x4C       ;   font byte of this character
sc_f1      = 0x4D       ;   of the next character
sc_jp      = 0x4E       ;   CH address of the next character
sc_fp      = 0x4F       ;   font page of the font row
sc_tle     = 0x50       ;   table pages: even byte, this character (SL)
sc_tre     = 0x51       ;     even byte, next character (SR)
sc_tlo     = 0x52       ;     odd byte, this character
sc_tro     = 0x53       ;     odd byte, next character

; screen places (80 column text)
SPIN_COL   = 13         ; text spinner, row 6
CLK_COL    = 37         ; uptime digits hh at 37, mm at 40, ss at 43, row 6
FRM_COL    = 58         ; frame count, row 6
PAGE_COL   = 37         ; RAM test page, row 7
PASS_COL   = 47         ; RAM test passes, row 7
ERR_COL    = 63         ; RAM test errors, row 7
BAR_COL    = 11         ; progress bar, row 8, one cell per 2 pages
NPAGES     = 25         ; RAM test pages per pass
NBAR       = 13         ; progress bar cells
NPAT       = 14         ; RAM test patterns per page (0-11 fixed values,
NFIXED     = 12         ;   12-13 the address XOR a value)
SC_X0      = 0x71       ; scroller: row offset of font row 0 (row 336, 2x)

; tables (ROM)
; text_demo_tables.asm (gen_text_demo_tables.py) has EXP2_LO-EXP4_3
; (x9000-x95FF), the scroller tables (x9800-xA2FF), HUE (xA300), the ring
; (xA400-xA6FF) and the unrolled RAM test routines (xA700-xAFFF)
TBL        = 0x1C00     ; small tables, one page each (see the end of
TBL2       = 0x3800     ;   this file)

; ===========================================================================
; main: draw the screen, then run the frame loop
; ===========================================================================
#addr 0x2400
main:
    ld   td_main >> 8, y        ; (the menu ROM puts its own jump at x6000
    jmp  td_main                ; and starts the demo at td_main)
td_main:
    ld   STACK_TOP, ac          ; stack first
    ld   ac, [SP]
    ld   0x50, y                ; map 07: sections 0-2 read RAM, so the RAM
    ld   0x07, [y,x]            ; test can use x2000-x3FFF too (this program
    ld   0x07, ac               ; keeps all its code and tables at x6000 up)
    ld   ac, [MAP_SHADOW]

    ld   LINK_LO, x             ; CALL con_clear: all 1 bpp 1x, cursor 0, 0
    ld   td_m1, [x]
    ld   LINK_HI, x
    ld   td_m1 >> 8, [x]
    ld   con_clear >> 8, y
    jmp  con_clear
td_m1:
    ; row mode bytes: rows 96-223 (x5A80-x5AFF) 4 bpp 4x = 0A,
    ; rows 224-351 (x5B00-x5B7F) 2 bpp 2x = 05, rows 352-479 (x5B80-x5BFF)
    ; 8 bpp 4x = 0B.  Rows 0-95 stay 1 bpp 1x (00).
    ld   0x5A, y
    ld   0x80, ac
td_mb1:
    ld   ac, x
    ld   0x0A, [y,x]
    inc
    bne  td_mb1
    ld   0x5B, y
    clr  ac
td_mb2:
    ld   ac, x
    ld   0x05, [y,x]
    inc
    blt  td_mb2_b7
    bra  td_mb2
td_mb2_b7:
td_mb3:
    ld   ac, x
    ld   0x0B, [y,x]
    inc
    bne  td_mb3
    ld   LINK_LO, x             ; CALL td_tint_init: rows 0-95 get their
    ld   td_mb4, [x]            ; tints (TINTB)
    ld   LINK_HI, x
    ld   td_mb4 >> 8, [x]
    ld   td_tint_init >> 8, y
    jmp  td_tint_init
td_mb4:

    ; ---- 80 column text -------------------------------------------------
    ld   text_a, ac             ; the text list
    ld   ac, [tp_lo]
    ld   text_a >> 8, ac
    ld   ac, [tp_hi]
    ld   LINK_LO, x             ; CALL td_text_list
    ld   td_m2, [x]
    ld   LINK_HI, x
    ld   td_m2 >> 8, [x]
    ld   td_text_list >> 8, y
    jmp  td_text_list
td_m2:
    ld   1, ac                  ; character set 20-6F on row 2
    ld   ac, [pr_inc]
    clr  ac
    ld   ac, [CUR_COL]
    ld   ac, [s_attr]
    ld   2, ac
    ld   ac, [CUR_ROW]
    ld   80, ac
    ld   ac, [pr_n]
    ld   0x20, ac
    ld   LINK_LO, x             ; CALL td_put_range
    ld   td_m3, [x]
    ld   LINK_HI, x
    ld   td_m3 >> 8, [x]
    ld   td_put_range >> 8, y
    jmp  td_put_range
td_m3:
    clr  ac                     ; 70-7E on row 3
    ld   ac, [CUR_COL]
    ld   3, ac
    ld   ac, [CUR_ROW]
    ld   15, ac
    ld   ac, [pr_n]
    ld   0x70, ac
    ld   LINK_LO, x             ; CALL td_put_range
    ld   td_m4, [x]
    ld   LINK_HI, x
    ld   td_m4 >> 8, [x]
    ld   td_put_range >> 8, y
    jmp  td_put_range
td_m4:
    clr  ac                     ; 20-6F in inverse video on row 4
    ld   ac, [CUR_COL]
    ld   4, ac
    ld   ac, [CUR_ROW]
    ld   80, ac
    ld   ac, [pr_n]
    ld   0x80, ac
    ld   ac, [s_attr]
    ld   0x20, ac
    ld   LINK_LO, x             ; CALL td_put_range
    ld   td_m5, [x]
    ld   LINK_HI, x
    ld   td_m5 >> 8, [x]
    ld   td_put_range >> 8, y
    jmp  td_put_range
td_m5:
    clr  ac                     ; progress bar: 43 dots
    ld   ac, [pr_inc]
    ld   ac, [s_attr]
    ld   BAR_COL, ac
    ld   ac, [CUR_COL]
    ld   8, ac
    ld   ac, [CUR_ROW]
    ld   NBAR, ac
    ld   ac, [pr_n]
    ld   0x2E, ac
    ld   LINK_LO, x             ; CALL td_put_range
    ld   td_m6, [x]
    ld   LINK_HI, x
    ld   td_m6 >> 8, [x]
    ld   td_put_range >> 8, y
    jmp  td_put_range
td_m6:
    ; ---- 16 colors: 4 bpp, 4x, rows 96-223 ------------------------------
    ld   s_16col, ac            ; "16 COLORS" in rainbow letters
    ld   ac, [R0]
    ld   s_16col >> 8, ac
    ld   ac, [R1]
    ld   2, ac
    ld   ac, [c_col]
    clr  ac
    ld   ac, [c_row]
    ld   ac, [c_bg]
    ld   LINK_LO, x             ; CALL td_puts4
    ld   td_m7, [x]
    ld   LINK_HI, x
    ld   td_m7 >> 8, [x]
    ld   td_puts4 >> 8, y
    jmp  td_puts4
td_m7:
    ld   td_bars >> 8, y
    jmp  td_bars

; ---------------------------------------------------------------------------
#addr 0x2500
td_bars:
    clr  ac                     ; 16 color bars, 3 bytes (6 pixels) wide,
    ld   ac, [i0]               ; block rows 10-30
td_bb:
    ld   [i0], ac               ; fill = color * x11
    shl
    shl
    shl
    shl
    or   [i0], ac
    ld   ac, [p_val]
    ld   [i0], ac               ; byte column 2 + 3 * color
    shl
    add  [i0], ac
    add  2, ac
    ld   ac, [p_col]
    ld   96 + 4 * 10, ac
    ld   ac, [p_rlo]
    clr  ac
    ld   ac, [p_rhi]
    ld   3, ac
    ld   ac, [p_n]
    ld   21, ac
    ld   ac, [p_rows]
    ld   4, ac
    ld   ac, [p_step]
    ld   LINK_LO, x             ; CALL td_rect
    ld   td_bb1, [x]
    ld   LINK_HI, x
    ld   td_bb1 >> 8, [x]
    ld   td_rect >> 8, y
    jmp  td_rect
td_bb1:
    ld   [i0], ac
    inc
    ld   ac, [i0]
    sub  16, ac
    bne  td_bb

    ; ---- 40 column text: 2 bpp, 2x, rows 224-351 ------------------------
    ld   text_c, ac
    ld   ac, [tp_lo]
    ld   text_c >> 8, ac
    ld   ac, [tp_hi]
    ld   LINK_LO, x             ; CALL td_text2_list
    ld   td_bb2, [x]
    ld   LINK_HI, x
    ld   td_bb2 >> 8, [x]
    ld   td_text2_list >> 8, y
    jmp  td_text2_list
td_bb2:
    ld   td_grid >> 8, y
    jmp  td_grid

; ---------------------------------------------------------------------------
#addr 0x2600
td_grid:
    ; ---- 256 colors: 8 bpp, 4x, rows 352-479 ----------------------------
    ; "256" in big digits on the left: each font pixel is 2 x 4 pixels
    ; (16 x 16 screen pixels), the digits 14 pixels apart from byte column
    ; 2, block rows 2-29.  Each font row of a digit gets the next shade of
    ; its color (SHADES): the 2 in reds, the 5 in blues, the 6 in greens.
    ; The ring on the right is drawn every frame (td_ring).
    clr  ac
    ld   ac, [i0]               ; digit
td_g_d:
    clr  ac
    ld   ac, [i1]               ; font row
td_g_r:
    ld   TBL2 >> 8, y           ; character
    ld   [i0], ac
    add  DIGITS & 0xFF, ac
    ld   ac, x
    ld   [y,x], ac
    ld   ac, [c_ch]
    ld   [i1], ac               ; font byte
    add  LIB_FONT >> 8, ac
    ld   ac, y
    ld   [c_ch], x
    ld   [y,x], ac
    ld   ac, [c_fr]
    ld   TBL2 >> 8, y           ; shade = SHADES[8 * digit + font row]
    ld   [i0], ac
    shl
    shl
    shl
    add  [i1], ac
    add  SHADES & 0xFF, ac
    ld   ac, x
    ld   [y,x], ac
    ld   ac, [p_val]
    ld   [i0], ac               ; byte column 2 + 14 * digit = 16 d - 2 d + 2
    shl
    ld   ac, [c_col]
    shl
    shl
    shl
    sub  [c_col], ac
    add  2, ac
    ld   ac, [c_col]
    clr  ac
    ld   ac, [c_i]              ; font pixel 0-5
td_g_b:
    ld   [c_fr], ac
    and  1, ac
    beq  td_g_nb
    ld   [c_col], ac
    ld   ac, [p_col]
    ld   [i1], ac               ; row 360 + 16 * font row = x168 + 16 r
    shl
    shl
    shl
    shl
    add  0x68, ac
    ld   ac, [p_rlo]
    ld   1, ac
    ld   ac, [p_rhi]
    ld   2, ac
    ld   ac, [p_n]
    ld   4, ac
    ld   ac, [p_rows]
    ld   ac, [p_step]
    ld   LINK_LO, x             ; CALL td_rect
    ld   td_g_nb, [x]
    ld   LINK_HI, x
    ld   td_g_nb >> 8, [x]
    ld   td_rect >> 8, y
    jmp  td_rect
td_g_nb:
    ld   [c_fr], ac             ; next font pixel
    shr  ac
    ld   ac, [c_fr]
    ld   [c_col], ac
    add  2, ac
    ld   ac, [c_col]
    ld   [c_i], ac
    inc
    ld   ac, [c_i]
    sub  6, ac
    bne  td_g_b
    ld   [i1], ac               ; next font row (rows 0-6; row 7 is blank)
    inc
    ld   ac, [i1]
    sub  7, ac
    bne  td_g_r
    ld   [i0], ac
    inc
    ld   ac, [i0]
    sub  3, ac
    bne  td_g_d
    ld   td_vars >> 8, y
    jmp  td_vars

#addr 0x3600
td_vars:
    ; ---- variables ----------------------------------------------------
    ld   0x30, ac               ; uptime 00:00:00, frame count 00000
    ld   ac, [CLK + 0]
    ld   ac, [CLK + 1]
    ld   ac, [CLK + 2]
    ld   ac, [CLK + 3]
    ld   ac, [CLK + 4]
    ld   ac, [CLK + 5]
    ld   ac, [FRM + 0]
    ld   ac, [FRM + 1]
    ld   ac, [FRM + 2]
    ld   ac, [FRM + 3]
    ld   ac, [FRM + 4]
    ld   1, ac                  ; every divider runs out on the first frame
    ld   ac, [spin_div]
    ld   ac, [big_div]
    ld   60, ac
    ld   ac, [sec_div]
    clr  ac
    ld   ac, [spin_ph]
    ld   ac, [big_ph]
    ld   ac, [wh_ph]
    ld   ac, [rt_idx]
    ld   ac, [pass_lo]
    ld   ac, [pass_hi]
    ld   ac, [err_lo]
    ld   ac, [err_hi]
    ld   msg, ac                ; the scroller starts at the message start;
    ld   ac, [marq_lo]          ; the first frame steps scr_q from 7 to 0
    ld   msg >> 8, ac           ; and moves on one character, so start one
    ld   ac, [marq_hi]          ; character before it (the end of the
    ld   7, ac                  ; message wraps to the start)
    ld   ac, [scr_q]
    ld   (msg_end - 1) & 0xFF, ac
    ld   ac, [marq_lo]
    ld   (msg_end - 1) >> 8, ac
    ld   ac, [marq_hi]
    ld   [FRAME_LO], ac
    ld   ac, [last_frame]
    ld   td_loop >> 8, y
    jmp  td_loop

; ===========================================================================
; the frame loop
; ===========================================================================
#addr 0x2700
td_loop:
    ld   LINK_LO, x             ; CALL frame_poll
    ld   td_l1, [x]
    ld   LINK_HI, x
    ld   td_l1 >> 8, [x]
    ld   frame_poll >> 8, y
    jmp  frame_poll
td_l1:
    ld   [FRAME_LO], ac         ; wait for a new frame
    xor  [last_frame], ac
    beq  td_loop
    ld   [FRAME_LO], ac
    ld   ac, [last_frame]

    ld   LINK_LO, x             ; CALL td_tint: the raster bar, while the
    ld   td_lt, [x]             ; video is still in vertical blanking
    ld   LINK_HI, x
    ld   td_lt >> 8, [x]
    ld   td_tint >> 8, y
    jmp  td_tint
td_lt:
    ld   LINK_LO, x             ; CALL menu_poll: back to the program menu
    ld   td_l0, [x]             ; on Esc or when the time is up (only in the
    ld   LINK_HI, x             ; menu ROM, docs/software/MENU.md)
    ld   td_l0 >> 8, [x]
    ld   menu_poll >> 8, y
    jmp  menu_poll
td_l0:
    ld   LINK_LO, x             ; CALL td_ram_page: test one page
    ld   td_l2, [x]
    ld   LINK_HI, x
    ld   td_l2 >> 8, [x]
    ld   td_ram_page >> 8, y
    jmp  td_ram_page
td_l2:
    ld   LINK_LO, x             ; CALL td_tick_frames
    ld   td_l3, [x]
    ld   LINK_HI, x
    ld   td_l3 >> 8, [x]
    ld   td_tick_frames >> 8, y
    jmp  td_tick_frames
td_l3:
    ld   [spin_div], ac         ; text spinner every 4 frames
    dec
    ld   ac, [spin_div]
    bne  td_l4
    ld   4, ac
    ld   ac, [spin_div]
    ld   [spin_ph], ac
    inc
    and  3, ac
    ld   ac, [spin_ph]
    add  SPIN & 0xFF, ac
    ld   ac, x
    ld   TBL >> 8, y
    ld   [y,x], ac
    ld   ac, [tb_v]
    ld   SPIN_COL, ac
    ld   ac, [CUR_COL]
    ld   6, ac
    ld   ac, [CUR_ROW]
    ld   [tb_v], ac
    ld   LINK_LO, x             ; CALL con_putc
    ld   td_l4, [x]
    ld   LINK_HI, x
    ld   td_l4 >> 8, [x]
    ld   con_putc >> 8, y
    jmp  con_putc
td_l4:
    ld   [big_div], ac          ; wheel every 3 frames
    dec
    ld   ac, [big_div]
    bne  td_l5
    ld   3, ac
    ld   ac, [big_div]
    ld   [big_ph], ac
    inc
    and  7, ac
    ld   ac, [big_ph]
    ld   LINK_LO, x             ; CALL td_wheel
    ld   td_l5, [x]
    ld   LINK_HI, x
    ld   td_l5 >> 8, [x]
    ld   td_wheel >> 8, y
    jmp  td_wheel
td_l5:
    ld   [sec_div], ac          ; uptime clock every 60 frames
    dec
    ld   ac, [sec_div]
    bne  td_l6
    ld   60, ac
    ld   ac, [sec_div]
    ld   LINK_LO, x             ; CALL td_tick_clock
    ld   td_l6, [x]
    ld   LINK_HI, x
    ld   td_l6 >> 8, [x]
    ld   td_tick_clock >> 8, y
    jmp  td_tick_clock
td_l6:
    ld   LINK_LO, x             ; CALL td_scroll: the message, one pixel
    ld   td_l7, [x]             ; a frame
    ld   LINK_HI, x
    ld   td_l7 >> 8, [x]
    ld   td_scroll >> 8, y
    jmp  td_scroll
td_l7:
    ld   LINK_LO, x             ; CALL td_ring: the 256-color ring, one
    ld   td_l8, [x]             ; step a frame
    ld   LINK_HI, x
    ld   td_l8 >> 8, [x]
    ld   td_ring >> 8, y
    jmp  td_ring
td_l8:
    ld   td_loop >> 8, y
    jmp  td_loop

; ===========================================================================
; td_ram_page - test one page of the RAM test and show the result
;   Writes each of the NPAT patterns to the whole page and reads it back.
;   Patterns 0-11 are fixed values (PAT_P): rt_wconst writes the value,
;   and the page is right when the OR of all its bytes and the AND of all
;   its bytes are both the value (rt_or, rt_and, unrolled in
;   text_demo_tables.asm).  Patterns 12-13 are the low address byte XOR
;   PAT_P XOR (pass_lo XOR page), so they change every pass, written and
;   read back byte by byte.  A pattern that reads back wrong counts one
;   ERROR.  Then marks the progress bar (one cell per two pages), shows the
;   page, PASS and ERRORS, and moves on to the next page.
; ===========================================================================
#addr 0x2800
td_ram_page:
    ld   ac, [SAVE_AC]          ; PUSH_LINK
    ld   [SP], x
    ld   [LINK_HI], ac
    ld   ac, [x]
    ld   [SP], ac
    dec
    ld   ac, x
    dec
    ld   ac, [SP]
    ld   [LINK_LO], ac
    ld   ac, [x]
    ld   [SAVE_AC], ac

    ld   [rt_idx], ac           ; page = PAGES[rt_idx]
    add  PAGES & 0xFF, ac
    ld   ac, x
    ld   TBL2 >> 8, y
    ld   [y,x], ac
    ld   ac, [rt_page]
    ld   [rt_idx], ac           ; a new bar cell on an even page
    and  1, ac
    bne  td_rp_odd
    ld   ac, [rt_bad]
td_rp_odd:
    clr  ac
    ld   ac, [rt_pat]
td_rp_pat:
    ld   TBL >> 8, y            ; rt_pv = PAT_P[rt_pat]
    ld   [rt_pat], ac
    add  PAT_P & 0xFF, ac
    ld   ac, x
    ld   [y,x], ac
    ld   ac, [rt_pv]
    ld   [rt_pat], ac
    sub  NFIXED, ac
    bcs  td_rp_fixed            ; a borrow: a fixed value
    ld   [pass_lo], ac          ; rt_pv ^= pass ^ page
    xor  [rt_page], ac
    xor  [rt_pv], ac
    ld   ac, [rt_pv]
    ld   [rt_page], y
    clr  ac
td_rp_wr:                       ; AC = rt_i = the byte in the page
    ld   ac, x                  ; [page, X] = X ^ pv
    ld   ac, [rt_i]
    xor  [rt_pv], ac
    ld   ac, [y,x]
    ld   [rt_i], ac
    inc
    bne  td_rp_wr
td_rp_vf:
    ld   ac, x                  ; read it back
    ld   ac, [rt_i]
    xor  [rt_pv], ac
    xor  [y,x], ac
    bne  td_rp_bad
    ld   [rt_i], ac
    inc
    bne  td_rp_vf
    bra  td_rp_next
td_rp_fixed:
    ld   [rt_pv], ac            ; write the value
    ld   LINK_LO, x             ; CALL rt_wconst
    ld   td_rp_f1, [x]
    ld   LINK_HI, x
    ld   td_rp_f1 >> 8, [x]
    ld   rt_wconst >> 8, y
    jmp  rt_wconst
td_rp_f1:
    clr  ac                     ; OR of the page
    ld   LINK_LO, x             ; CALL rt_or
    ld   td_rp_f2, [x]
    ld   LINK_HI, x
    ld   td_rp_f2 >> 8, [x]
    ld   rt_or >> 8, y
    jmp  rt_or
td_rp_f2:
    xor  [rt_pv], ac
    bne  td_rp_bad
    ld   0xFF, ac               ; AND of the page
    ld   LINK_LO, x             ; CALL rt_and
    ld   td_rp_f3, [x]
    ld   LINK_HI, x
    ld   td_rp_f3 >> 8, [x]
    ld   rt_and >> 8, y
    jmp  rt_and
td_rp_f3:
    xor  [rt_pv], ac
    beq  td_rp_next
td_rp_bad:
    ld   1, ac                  ; a failed check
    ld   ac, [rt_bad]
    ld   [err_lo], ac
    inc
    ld   ac, [err_lo]
    bne  td_rp_next
    ld   [err_hi], ac
    inc
    ld   ac, [err_hi]
td_rp_next:
    ld   [rt_pat], ac
    inc
    ld   ac, [rt_pat]
    sub  NPAT, ac
    bne  td_rp_pat
    ld   td_rp_show >> 8, y
    jmp  td_rp_show

#addr 0x2900
td_rp_show:
    ld   [rt_idx], ac           ; progress bar cell: block, or inverse E
    shr  ac
    add  BAR_COL, ac
    ld   ac, [CUR_COL]
    ld   8, ac
    ld   ac, [CUR_ROW]
    ld   [rt_bad], ac
    beq  td_rp_blk
    ld   0xC5, ac
    bra  td_rp_put
td_rp_blk:
    ld   0xA0, ac
td_rp_put:
    ld   LINK_LO, x             ; CALL con_putc
    ld   td_rp1, [x]
    ld   LINK_HI, x
    ld   td_rp1 >> 8, [x]
    ld   con_putc >> 8, y
    jmp  con_putc
td_rp1:
    ld   PAGE_COL, ac           ; page address
    ld   ac, [CUR_COL]
    ld   7, ac
    ld   ac, [CUR_ROW]
    ld   [rt_page], ac
    ld   LINK_LO, x             ; CALL con_hex8
    ld   td_rp2, [x]
    ld   LINK_HI, x
    ld   td_rp2 >> 8, [x]
    ld   con_hex8 >> 8, y
    jmp  con_hex8
td_rp2:
    ld   ERR_COL, ac            ; errors
    ld   ac, [CUR_COL]
    ld   [err_lo], ac
    ld   ac, [R0]
    ld   [err_hi], ac
    ld   ac, [R1]
    ld   LINK_LO, x             ; CALL con_dec16
    ld   td_rp3, [x]
    ld   LINK_HI, x
    ld   td_rp3 >> 8, [x]
    ld   con_dec16 >> 8, y
    jmp  con_dec16
td_rp3:
    ld   [rt_idx], ac           ; next page
    inc
    ld   ac, [rt_idx]
    sub  NPAGES, ac
    bne  td_rp_more
    ld   td_rp_pass >> 8, y
    jmp  td_rp_pass
td_rp_more:
    ld   lib_leave >> 8, y      ; LEAVE
    jmp  lib_leave

td_rp_pass:
    clr  ac                     ; end of a pass: back to the first page
    ld   ac, [rt_idx]
    ld   [pass_lo], ac
    inc
    ld   ac, [pass_lo]
    bne  td_rp_p1
    ld   [pass_hi], ac
    inc
    ld   ac, [pass_hi]
td_rp_p1:
    ld   PASS_COL, ac           ; passes
    ld   ac, [CUR_COL]
    ld   [pass_lo], ac
    ld   ac, [R0]
    ld   [pass_hi], ac
    ld   ac, [R1]
    ld   LINK_LO, x             ; CALL con_dec16
    ld   td_rp4, [x]
    ld   LINK_HI, x
    ld   td_rp4 >> 8, [x]
    ld   con_dec16 >> 8, y
    jmp  con_dec16
td_rp4:
    clr  ac                     ; progress bar back to dots
    ld   ac, [pr_inc]
    ld   ac, [s_attr]
    ld   BAR_COL, ac
    ld   ac, [CUR_COL]
    ld   8, ac
    ld   ac, [CUR_ROW]
    ld   NBAR, ac
    ld   ac, [pr_n]
    ld   0x2E, ac
    ld   LINK_LO, x             ; CALL td_put_range
    ld   td_rp5, [x]
    ld   LINK_HI, x
    ld   td_rp5 >> 8, [x]
    ld   td_put_range >> 8, y
    jmp  td_put_range
td_rp5:
    ld   lib_leave >> 8, y      ; LEAVE
    jmp  lib_leave

; ===========================================================================
; td_tick_frames - add one to the frame count and show it
; td_tick_clock  - add one second to the uptime clock and show it
; ===========================================================================
#addr 0x2A00
td_tick_frames:
    ld   ac, [SAVE_AC]          ; PUSH_LINK
    ld   [SP], x
    ld   [LINK_HI], ac
    ld   ac, [x]
    ld   [SP], ac
    dec
    ld   ac, x
    dec
    ld   ac, [SP]
    ld   [LINK_LO], ac
    ld   ac, [x]
    ld   [SAVE_AC], ac
    ld   4, ac                  ; last digit first
td_tf_d:
    ld   ac, [dg_i]
    add  FRM, x                 ; X = FRM + digit
    ld   [x], ac
    inc
    ld   ac, [x]
    sub  0x3A, ac
    bne  td_tf_show
    ld   0x30, [x]              ; 9 + 1: 0 and carry
    ld   [dg_i], ac
    sub  1, ac
    bcc  td_tf_d                ; a borrow: it was the first digit
td_tf_show:
    ld   FRM_COL, ac
    ld   ac, [CUR_COL]
    ld   6, ac
    ld   ac, [CUR_ROW]
    ld   FRM, ac
    ld   ac, [R0]
    ld   5, ac
    ld   ac, [pz_n]
    ld   LINK_LO, x             ; CALL td_print_zp
    ld   td_tf1, [x]
    ld   LINK_HI, x
    ld   td_tf1 >> 8, [x]
    ld   td_print_zp >> 8, y
    jmp  td_print_zp
td_tf1:
    ld   lib_leave >> 8, y      ; LEAVE
    jmp  lib_leave

td_tick_clock:
    ld   ac, [SAVE_AC]          ; PUSH_LINK
    ld   [SP], x
    ld   [LINK_HI], ac
    ld   ac, [x]
    ld   [SP], ac
    dec
    ld   ac, x
    dec
    ld   ac, [SP]
    ld   [LINK_LO], ac
    ld   ac, [x]
    ld   [SAVE_AC], ac
    ld   TBL >> 8, y            ; TBL + x29.. holds each digit's limit
    ld   5, ac                  ; seconds digit first
td_tc_d:
    ld   ac, [dg_i]
    add  CLK, x                 ; X = CLK + digit
    ld   [x], ac
    inc
    ld   ac, [x]
    xor  [y,x], ac
    bne  td_tc_show
    ld   0x30, [x]              ; at its limit: 0 and carry
    ld   [dg_i], ac
    sub  1, ac
    bcc  td_tc_d                ; a borrow: it was the first digit
td_tc_show:
    ld   CLK_COL, ac            ; hh
    ld   ac, [CUR_COL]
    ld   6, ac
    ld   ac, [CUR_ROW]
    ld   CLK, ac
    ld   ac, [R0]
    ld   2, ac
    ld   ac, [pz_n]
    ld   LINK_LO, x             ; CALL td_print_zp
    ld   td_tc1, [x]
    ld   LINK_HI, x
    ld   td_tc1 >> 8, [x]
    ld   td_print_zp >> 8, y
    jmp  td_print_zp
td_tc1:
    ld   CLK_COL + 3, ac        ; mm
    ld   ac, [CUR_COL]
    ld   CLK + 2, ac
    ld   ac, [R0]
    ld   2, ac
    ld   ac, [pz_n]
    ld   LINK_LO, x             ; CALL td_print_zp
    ld   td_tc2, [x]
    ld   LINK_HI, x
    ld   td_tc2 >> 8, [x]
    ld   td_print_zp >> 8, y
    jmp  td_print_zp
td_tc2:
    ld   CLK_COL + 6, ac        ; ss
    ld   ac, [CUR_COL]
    ld   CLK + 4, ac
    ld   ac, [R0]
    ld   2, ac
    ld   ac, [pz_n]
    ld   LINK_LO, x             ; CALL td_print_zp
    ld   td_tc3, [x]
    ld   LINK_HI, x
    ld   td_tc3 >> 8, [x]
    ld   td_print_zp >> 8, y
    jmp  td_print_zp
td_tc3:
    ld   lib_leave >> 8, y      ; LEAVE
    jmp  lib_leave

; ===========================================================================
; td_wheel - draw the 16-color wheel for phase big_ph
;   Eight 4 x 4 pixel dots on a circle in the 4 bpp band; dot k gets color
;   TAIL[(big_ph - k) & 7], so the white dot leads a fading tail and the
;   wheel turns clockwise as big_ph counts up.
; ===========================================================================
#addr 0x2B00
td_wheel:
    ld   ac, [SAVE_AC]          ; PUSH_LINK
    ld   [SP], x
    ld   [LINK_HI], ac
    ld   ac, [x]
    ld   [SP], ac
    dec
    ld   ac, x
    dec
    ld   ac, [SP]
    ld   [LINK_LO], ac
    ld   ac, [x]
    ld   [SAVE_AC], ac
    clr  ac
    ld   ac, [dot_k]
td_wh_dot:
    ld   TBL >> 8, y
    ld   [big_ph], ac           ; color
    sub  [dot_k], ac
    and  7, ac
    add  TAIL & 0xFF, ac
    ld   ac, x
    ld   [y,x], ac
    ld   ac, [p_val]
    ld   [dot_k], ac            ; place
    add  DOTC & 0xFF, ac
    ld   ac, x
    ld   [y,x], ac
    ld   ac, [p_col]
    ld   [dot_k], ac
    add  DOTR & 0xFF, ac
    ld   ac, x
    ld   [y,x], ac
    ld   ac, [p_rlo]
    clr  ac
    ld   ac, [p_rhi]
    ld   2, ac
    ld   ac, [p_n]
    ld   4, ac
    ld   ac, [p_rows]
    ld   ac, [p_step]
    ld   LINK_LO, x             ; CALL td_rect
    ld   td_wh1, [x]
    ld   LINK_HI, x
    ld   td_wh1 >> 8, [x]
    ld   td_rect >> 8, y
    jmp  td_rect
td_wh1:
    ld   [dot_k], ac
    inc
    ld   ac, [dot_k]
    sub  8, ac
    bne  td_wh_dot
    ld   lib_leave >> 8, y      ; LEAVE
    jmp  lib_leave

; ===========================================================================
; td_scroll - the message on text row 7 of the 40 column band (rows
;   336-351), moved one pixel left each frame
;   scr_q is the pixel (0-7) of the first character, CH + 0 that the left
;   edge shows; CH holds the 41 characters on the screen (40 and the one
;   coming in).  Each font row of each character pair f0 f1 makes two
;   bytes: pixels q to q+3 and q+4 to q+7 of the 16, from the tables
;   SL_p[f0] OR SR_p[f1] (text_demo_tables.asm), as gold on blue.  At 8
;   pixels the window moves on one character (td_fill_ch).
; ===========================================================================
#addr 0x2C00
td_scroll:
    ld   ac, [SAVE_AC]          ; PUSH_LINK
    ld   [SP], x
    ld   [LINK_HI], ac
    ld   ac, [x]
    ld   [SP], ac
    dec
    ld   ac, x
    dec
    ld   ac, [SP]
    ld   [LINK_LO], ac
    ld   ac, [x]
    ld   [SAVE_AC], ac
    ld   [scr_q], ac            ; next pixel
    inc
    and  7, ac
    ld   ac, [scr_q]
    bne  td_sc_pages
    ld   [marq_hi], y           ; next character: move the start on,
    ld   [marq_lo], ac          ; wrapping at the 00 at the end
    inc
    ld   ac, [marq_lo]
    bne  td_sc_1
    ld   [marq_hi], ac
    inc
    ld   ac, [marq_hi]
    ld   ac, y
td_sc_1:
    ld   [marq_lo], x
    ld   [y,x], ac
    bne  td_sc_2
    ld   msg, ac
    ld   ac, [marq_lo]
    ld   msg >> 8, ac
    ld   ac, [marq_hi]
td_sc_2:
    ld   LINK_LO, x             ; CALL td_fill_ch
    ld   td_sc_pages, [x]
    ld   LINK_HI, x
    ld   td_sc_pages >> 8, [x]
    ld   td_fill_ch >> 8, y
    jmp  td_fill_ch
td_sc_pages:
    ld   SC_LPAGE >> 8, y       ; the table pages for p = q and q + 4
    ld   [scr_q], ac
    ld   ac, x
    ld   [y,x], ac
    ld   ac, [sc_tle]
    ld   [scr_q], ac
    add  0x10, x                ; SC_RPAGE = SC_LPAGE + x10
    ld   [y,x], ac
    ld   ac, [sc_tre]
    ld   [scr_q], ac
    add  4, x
    ld   [y,x], ac
    ld   ac, [sc_tlo]
    ld   [scr_q], ac
    add  0x14, x
    ld   [y,x], ac
    ld   ac, [sc_tro]
    ld   LIB_FONT >> 8, ac      ; font row 0
    ld   ac, [sc_fp]
    ld   SC_X0, ac
    ld   ac, [sc_vx]
td_sc_row:
    ld   0x61, ac               ; byte columns 0 and 1 (2x rows: odd pages)
    ld   ac, [sc_vy]
    ld   0x63, ac
    ld   ac, [sc_vo]
    ld   [CH], x                ; f0 = the first character's font byte
    ld   [sc_fp], y
    ld   [y,x], ac
    ld   ac, [sc_f0]
    ld   CH + 1, ac
    ld   ac, [sc_jp]
td_sc_ch:
    ld   [sc_jp], x             ; f1 = the next character's font byte
    ld   [x], ac
    ld   ac, x
    ld   [sc_fp], y
    ld   [y,x], ac
    ld   ac, [sc_f1]
    ld   ac, x                  ; even byte: SR[f1] OR SL[f0]
    ld   [sc_tre], y
    ld   [y,x], ac
    ld   [sc_f0], x
    ld   [sc_tle], y
    or   [y,x], ac
    xor  0x55, ac               ; mask AND (gold XOR blue = FF) XOR blue
    ld   [sc_vy], y
    ld   [sc_vx], x
    ld   ac, [y,x]
    ld   [sc_f1], x             ; odd byte
    ld   [sc_tro], y
    ld   [y,x], ac
    ld   [sc_f0], x
    ld   [sc_tlo], y
    or   [y,x], ac
    xor  0x55, ac
    ld   [sc_vo], y
    ld   [sc_vx], x
    ld   ac, [y,x]
    ld   [sc_vy], ac            ; two byte columns on: 4 pages
    add  4, ac
    ld   ac, [sc_vy]
    add  2, ac
    ld   ac, [sc_vo]
    ld   [sc_f1], ac            ; the next character
    ld   ac, [sc_f0]
    ld   [sc_jp], ac
    inc
    ld   ac, [sc_jp]
    sub  CH + 41, ac
    bne  td_sc_ch
    ld   [sc_fp], ac            ; next font row: the next font page and
    inc                         ; the next 2x row pair
    ld   ac, [sc_fp]
    ld   [sc_vx], ac
    add  2, ac
    ld   ac, [sc_vx]
    sub  SC_X0 + 16, ac
    bne  td_sc_row
    ld   lib_leave >> 8, y      ; LEAVE
    jmp  lib_leave

; ---------------------------------------------------------------------------
; td_fill_ch - copy the 41 message characters from marq_hi:marq_lo to CH,
;   wrapping at the 00 at the end of the message
;   (a leaf routine; changes AC, X, Y, R0, R1, T2)
; ---------------------------------------------------------------------------
#addr 0x3700
td_fill_ch:
    ld   [marq_lo], ac
    ld   ac, [R0]
    ld   [marq_hi], ac
    ld   ac, [R1]
    ld   CH, ac
    ld   ac, [T2]
td_fc_ch:
    ld   [R1], y
    ld   [R0], x
    ld   [y,x], ac
    bne  td_fc_put
    ld   msg, ac                ; the end of the message: wrap
    ld   ac, [R0]
    ld   msg >> 8, ac
    ld   ac, [R1]
    bra  td_fc_ch
td_fc_put:
    ld   [T2], x
    ld   ac, [x]
    ld   [R0], ac
    inc
    ld   ac, [R0]
    bne  td_fc_1
    ld   [R1], ac
    inc
    ld   ac, [R1]
td_fc_1:
    ld   [T2], ac
    inc
    ld   ac, [T2]
    sub  CH + 41, ac
    bne  td_fc_ch
    ld   [LINK_HI], y           ; RETURN
    jmp  [LINK_LO]

; ---------------------------------------------------------------------------
; td_ring - the 256-color ring on the right of the 8 bpp band, one step
;   on: ring pixel k gets HUE[RING_A[k] + wh_ph], so the rainbow turns
;   once in 64 frames
;   (a leaf routine; changes AC, X, Y, wh_*)
; ---------------------------------------------------------------------------
td_ring:
    ld   [wh_ph], ac
    inc
    ld   ac, [wh_ph]
    clr  ac
    ld   ac, [wh_k]
td_rg_px:
    ld   [wh_k], x              ; color
    ld   RING_A >> 8, y
    ld   [y,x], ac
    add  [wh_ph], ac
    ld   ac, x
    ld   HUE >> 8, y
    ld   [y,x], ac
    ld   ac, [wh_t]
    ld   [wh_k], x              ; place
    ld   RING_X >> 8, y
    ld   [y,x], ac
    ld   ac, [wh_x]
    ld   RING_V >> 8, y
    ld   [y,x], ac
    ld   ac, y
    ld   [wh_x], x
    ld   [wh_t], ac
    ld   ac, [y,x]
    ld   [wh_k], ac
    inc
    ld   ac, [wh_k]
    sub  RING_N, ac
    bne  td_rg_px
    ld   [LINK_HI], y           ; RETURN
    jmp  [LINK_LO]

; ===========================================================================
; drawing routines
; ===========================================================================

; ---------------------------------------------------------------------------
; td_fill_run - write p_val to p_n bytes across, from byte column p_col,
;   on screen row p_rhi:p_rlo (any mode and line repeat, via vid_addr)
;   changes: AC, X, Y, R2, R3, T0, T1, T4, p_hi, p_cnt
; ---------------------------------------------------------------------------
#addr 0x2D00
td_fill_run:
    ld   ac, [SAVE_AC]          ; PUSH_LINK
    ld   [SP], x
    ld   [LINK_HI], ac
    ld   ac, [x]
    ld   [SP], ac
    dec
    ld   ac, x
    dec
    ld   ac, [SP]
    ld   [LINK_LO], ac
    ld   ac, [x]
    ld   [SAVE_AC], ac
    ld   [p_rlo], ac
    ld   ac, [R2]
    ld   [p_rhi], ac
    ld   ac, [R3]
    ld   [p_col], ac
    ld   LINK_LO, x             ; CALL vid_addr
    ld   td_fr1, [x]
    ld   LINK_HI, x
    ld   td_fr1 >> 8, [x]
    ld   vid_addr >> 8, y
    jmp  vid_addr
td_fr1:
    ld   ac, [p_hi]
    ld   [p_n], ac
    ld   ac, [p_cnt]
td_fr_loop:
    ld   [p_hi], y
    ld   [p_val], ac
    ld   ac, [y,x]
    ld   [p_hi], ac             ; next byte column: 2 pages on
    add  2, ac
    ld   ac, [p_hi]
    ld   [p_cnt], ac
    dec
    ld   ac, [p_cnt]
    bne  td_fr_loop
    ld   lib_leave >> 8, y      ; LEAVE
    jmp  lib_leave

; ---------------------------------------------------------------------------
; td_rect - fill p_rows rows, p_step apart, from row p_rhi:p_rlo, with
;   td_fill_run (p_val, p_col, p_n).  p_step is the band's line repeat, so
;   each row of video memory is written once.
;   changes: as td_fill_run, and p_rlo, p_rhi, p_rows
; ---------------------------------------------------------------------------
td_rect:
    ld   ac, [SAVE_AC]          ; PUSH_LINK
    ld   [SP], x
    ld   [LINK_HI], ac
    ld   ac, [x]
    ld   [SP], ac
    dec
    ld   ac, x
    dec
    ld   ac, [SP]
    ld   [LINK_LO], ac
    ld   ac, [x]
    ld   [SAVE_AC], ac
td_rc_row:
    ld   LINK_LO, x             ; CALL td_fill_run
    ld   td_rc1, [x]
    ld   LINK_HI, x
    ld   td_rc1 >> 8, [x]
    ld   td_fill_run >> 8, y
    jmp  td_fill_run
td_rc1:
    ld   [p_rlo], ac            ; row + step, carry into p_rhi
    add  [p_step], ac
    ld   ac, [p_rlo]
    bcc  td_rc_nc
    ld   [p_rhi], ac
    inc
    ld   ac, [p_rhi]
td_rc_nc:
    ld   [p_rows], ac
    dec
    ld   ac, [p_rows]
    bne  td_rc_row
    ld   lib_leave >> 8, y      ; LEAVE
    jmp  lib_leave

; ---------------------------------------------------------------------------
; td_put_gbuf - write gb0.. (p_n = 1-4 bytes) across from byte column
;   p_col on row p_rhi:p_rlo
;   changes: AC, X, Y, R2, R3, T0, T1, T4, p_hi, p_cnt
; ---------------------------------------------------------------------------
#addr 0x2E00
td_put_gbuf:
    ld   ac, [SAVE_AC]          ; PUSH_LINK
    ld   [SP], x
    ld   [LINK_HI], ac
    ld   ac, [x]
    ld   [SP], ac
    dec
    ld   ac, x
    dec
    ld   ac, [SP]
    ld   [LINK_LO], ac
    ld   ac, [x]
    ld   [SAVE_AC], ac
    ld   [p_rlo], ac
    ld   ac, [R2]
    ld   [p_rhi], ac
    ld   ac, [R3]
    ld   [p_col], ac
    ld   LINK_LO, x             ; CALL vid_addr
    ld   td_pg1, [x]
    ld   LINK_HI, x
    ld   td_pg1 >> 8, [x]
    ld   vid_addr >> 8, y
    jmp  vid_addr
td_pg1:
    ld   ac, y
    ld   ac, [p_hi]
    ld   [gb0], ac
    ld   ac, [y,x]
    ld   [p_n], ac
    dec
    beq  td_pg_done
    ld   ac, [p_cnt]
    ld   [p_hi], ac
    add  2, ac
    ld   ac, [p_hi]
    ld   ac, y
    ld   [gb1], ac
    ld   ac, [y,x]
    ld   [p_cnt], ac
    dec
    beq  td_pg_done
    ld   ac, [p_cnt]
    ld   [p_hi], ac
    add  2, ac
    ld   ac, [p_hi]
    ld   ac, y
    ld   [gb2], ac
    ld   ac, [y,x]
    ld   [p_cnt], ac
    dec
    beq  td_pg_done
    ld   [p_hi], ac
    add  2, ac
    ld   ac, y
    ld   [gb3], ac
    ld   ac, [y,x]
td_pg_done:
    ld   lib_leave >> 8, y      ; LEAVE
    jmp  lib_leave

; ---------------------------------------------------------------------------
; td_char2 - one 8 x 8 character on the 2 bpp, 2x band (rows 224-351)
;   in: c_ch, c_col = text column 0-39, c_row = text row 0-7,
;       c_fg = foreground fill XOR c_bg, c_bg = background fill
;       (fills: 00 black, 55 blue, AA gold, FF white)
;   Each font row is 2 bytes (8 pixels) on one 2x row pair, so the
;   character is 16 lines tall.
;   changes: AC, X, Y, R2, R3, T0, T1, T4, p_*, gb0, gb1, c_fr
; ---------------------------------------------------------------------------
td_char2:
    ld   ac, [SAVE_AC]          ; PUSH_LINK
    ld   [SP], x
    ld   [LINK_HI], ac
    ld   ac, [x]
    ld   [SP], ac
    dec
    ld   ac, x
    dec
    ld   ac, [SP]
    ld   [LINK_LO], ac
    ld   ac, [x]
    ld   [SAVE_AC], ac
    ld   [c_row], ac            ; row 224 + 16 * text row; the 8 font rows
    shl                         ; (+ 0-14) never cross a 256-row boundary
    shl
    shl
    shl
    add  224, ac
    ld   ac, [p_rlo]
    ld   1, ac                  ; high byte 1 from text row 2 on
    ld   ac, [p_rhi]
    ld   [c_row], ac
    sub  2, ac
    bcc  td_c2_hi
    clr  ac
    ld   ac, [p_rhi]
td_c2_hi:
    ld   [c_col], ac            ; 2 byte columns per character
    shl
    ld   ac, [p_col]
    clr  ac
    ld   ac, [c_fr]
    ld   td_c2_row >> 8, y
    jmp  td_c2_row
#addr 0x2F00
td_c2_row:
    ld   [c_fr], ac             ; font byte
    add  LIB_FONT >> 8, ac
    ld   ac, y
    ld   [c_ch], x
    ld   [y,x], ac
    ld   ac, x
    ld   EXP2_LO >> 8, y        ; pixels 0-3
    ld   [y,x], ac
    and  [c_fg], ac
    xor  [c_bg], ac
    ld   ac, [gb0]
    ld   EXP2_HI >> 8, y        ; pixels 4-7
    ld   [y,x], ac
    and  [c_fg], ac
    xor  [c_bg], ac
    ld   ac, [gb1]
    ld   2, ac
    ld   ac, [p_n]
    ld   LINK_LO, x             ; CALL td_put_gbuf
    ld   td_c2_1, [x]
    ld   LINK_HI, x
    ld   td_c2_1 >> 8, [x]
    ld   td_put_gbuf >> 8, y
    jmp  td_put_gbuf
td_c2_1:
    ld   [p_rlo], ac            ; next row pair
    add  2, ac
    ld   ac, [p_rlo]
    ld   [c_fr], ac
    inc
    ld   ac, [c_fr]
    sub  8, ac
    bne  td_c2_row
    ld   lib_leave >> 8, y      ; LEAVE
    jmp  lib_leave

; ---------------------------------------------------------------------------
; td_char4 - one 8 x 8 character on the 4 bpp, 4x band (rows 96-223)
;   in: c_ch, c_col = byte column (4 per character), c_row = block row
;       0-24 (4 lines each), c_fg = foreground fill XOR c_bg, c_bg
;       (fill = color * 11)
;   changes: AC, X, Y, R2, R3, T0, T1, T4, p_*, gb0-gb3, c_fr
; ---------------------------------------------------------------------------
td_char4:
    ld   ac, [SAVE_AC]          ; PUSH_LINK
    ld   [SP], x
    ld   [LINK_HI], ac
    ld   ac, [x]
    ld   [SP], ac
    dec
    ld   ac, x
    dec
    ld   ac, [SP]
    ld   [LINK_LO], ac
    ld   ac, [x]
    ld   [SAVE_AC], ac
    ld   [c_row], ac            ; row 96 + 4 * block row
    shl
    shl
    add  96, ac
    ld   ac, [p_rlo]
    clr  ac
    ld   ac, [p_rhi]
    ld   ac, [c_fr]
    ld   [c_col], ac
    ld   ac, [p_col]
    ld   td_c4_row >> 8, y
    jmp  td_c4_row
#addr 0x3000
td_c4_row:
    ld   [c_fr], ac             ; font byte
    add  LIB_FONT >> 8, ac
    ld   ac, y
    ld   [c_ch], x
    ld   [y,x], ac
    ld   ac, x
    ld   EXP4_0 >> 8, y         ; pixels 0-1
    ld   [y,x], ac
    and  [c_fg], ac
    xor  [c_bg], ac
    ld   ac, [gb0]
    ld   EXP4_1 >> 8, y         ; pixels 2-3
    ld   [y,x], ac
    and  [c_fg], ac
    xor  [c_bg], ac
    ld   ac, [gb1]
    ld   EXP4_2 >> 8, y         ; pixels 4-5
    ld   [y,x], ac
    and  [c_fg], ac
    xor  [c_bg], ac
    ld   ac, [gb2]
    ld   EXP4_3 >> 8, y         ; pixels 6-7
    ld   [y,x], ac
    and  [c_fg], ac
    xor  [c_bg], ac
    ld   ac, [gb3]
    ld   4, ac
    ld   ac, [p_n]
    ld   LINK_LO, x             ; CALL td_put_gbuf
    ld   td_c4_1, [x]
    ld   LINK_HI, x
    ld   td_c4_1 >> 8, [x]
    ld   td_put_gbuf >> 8, y
    jmp  td_put_gbuf
td_c4_1:
    ld   [p_rlo], ac            ; next block row
    add  4, ac
    ld   ac, [p_rlo]
    ld   [c_fr], ac
    inc
    ld   ac, [c_fr]
    sub  8, ac
    bne  td_c4_row
    ld   lib_leave >> 8, y      ; LEAVE
    jmp  lib_leave

; ---------------------------------------------------------------------------
; td_puts4 - string R1:R0 (ending in 00) on the 4 bpp band with td_char4,
;   from c_col, c_row, each character in the next RAINBOW color, c_bg = 00
;   changes: AC, X, Y, R0-R3, T0, T1, T4, c_col, c_i and as td_char4
; ---------------------------------------------------------------------------
#addr 0x3100
td_puts4:
    ld   ac, [SAVE_AC]          ; PUSH_LINK
    ld   [SP], x
    ld   [LINK_HI], ac
    ld   ac, [x]
    ld   [SP], ac
    dec
    ld   ac, x
    dec
    ld   ac, [SP]
    ld   [LINK_LO], ac
    ld   ac, [x]
    ld   [SAVE_AC], ac
    clr  ac
    ld   ac, [c_i]
td_p4_ch:
    ld   [R1], y
    ld   [R0], x
    ld   [y,x], ac
    beq  td_p4_done
    ld   ac, [c_ch]
    ld   [c_i], ac              ; color
    add  RAINBOW & 0xFF, ac
    ld   ac, x
    ld   TBL >> 8, y
    ld   [y,x], ac
    ld   ac, [c_fg]
    ld   LINK_LO, x             ; CALL td_char4
    ld   td_p4_1, [x]
    ld   LINK_HI, x
    ld   td_p4_1 >> 8, [x]
    ld   td_char4 >> 8, y
    jmp  td_char4
td_p4_1:
    ld   [c_col], ac
    add  4, ac
    ld   ac, [c_col]
    ld   [c_i], ac
    inc
    ld   ac, [c_i]
    ld   [R0], ac
    inc
    ld   ac, [R0]
    bne  td_p4_ch
    ld   [R1], ac
    inc
    ld   ac, [R1]
    bra  td_p4_ch
td_p4_done:
    ld   lib_leave >> 8, y      ; LEAVE
    jmp  lib_leave

; ---------------------------------------------------------------------------
; td_text2_list - draw a list of strings on the 40 column band
;   tp_hi:tp_lo = list of (text column, text row, fg XOR bg, bg, string low,
;   string high) entries, ending with FF
; ---------------------------------------------------------------------------
#addr 0x3200
td_text2_list:
    ld   ac, [SAVE_AC]          ; PUSH_LINK
    ld   [SP], x
    ld   [LINK_HI], ac
    ld   ac, [x]
    ld   [SP], ac
    dec
    ld   ac, x
    dec
    ld   ac, [SP]
    ld   [LINK_LO], ac
    ld   ac, [x]
    ld   [SAVE_AC], ac
td_t2_ent:
    ld   LINK_LO, x             ; CALL td_tbl_next: column, or FF
    ld   td_t2_1, [x]
    ld   LINK_HI, x
    ld   td_t2_1 >> 8, [x]
    ld   td_tbl_next >> 8, y
    jmp  td_tbl_next
td_t2_1:
    blt  td_t2_done
    ld   ac, [c_col]
    ld   LINK_LO, x             ; CALL td_tbl_next: row
    ld   td_t2_2, [x]
    ld   LINK_HI, x
    ld   td_t2_2 >> 8, [x]
    ld   td_tbl_next >> 8, y
    jmp  td_tbl_next
td_t2_2:
    ld   ac, [c_row]
    ld   LINK_LO, x             ; CALL td_tbl_next: fg XOR bg
    ld   td_t2_3, [x]
    ld   LINK_HI, x
    ld   td_t2_3 >> 8, [x]
    ld   td_tbl_next >> 8, y
    jmp  td_tbl_next
td_t2_3:
    ld   ac, [c_fg]
    ld   LINK_LO, x             ; CALL td_tbl_next: bg
    ld   td_t2_4, [x]
    ld   LINK_HI, x
    ld   td_t2_4 >> 8, [x]
    ld   td_tbl_next >> 8, y
    jmp  td_tbl_next
td_t2_4:
    ld   ac, [c_bg]
    ld   LINK_LO, x             ; CALL td_tbl_next: string low
    ld   td_t2_5, [x]
    ld   LINK_HI, x
    ld   td_t2_5 >> 8, [x]
    ld   td_tbl_next >> 8, y
    jmp  td_tbl_next
td_t2_5:
    ld   ac, [R0]
    ld   LINK_LO, x             ; CALL td_tbl_next: string high
    ld   td_t2_6, [x]
    ld   LINK_HI, x
    ld   td_t2_6 >> 8, [x]
    ld   td_tbl_next >> 8, y
    jmp  td_tbl_next
td_t2_6:
    ld   ac, [R1]
td_t2_ch:
    ld   [R1], y                ; the string
    ld   [R0], x
    ld   [y,x], ac
    beq  td_t2_ent
    ld   ac, [c_ch]
    ld   LINK_LO, x             ; CALL td_char2
    ld   td_t2_7, [x]
    ld   LINK_HI, x
    ld   td_t2_7 >> 8, [x]
    ld   td_char2 >> 8, y
    jmp  td_char2
td_t2_7:
    ld   [c_col], ac
    inc
    ld   ac, [c_col]
    ld   [R0], ac
    inc
    ld   ac, [R0]
    bne  td_t2_ch
    ld   [R1], ac
    inc
    ld   ac, [R1]
    bra  td_t2_ch
td_t2_done:
    ld   lib_leave >> 8, y      ; LEAVE
    jmp  lib_leave

; ---------------------------------------------------------------------------
; td_text_list - print a list of strings with the console
;   tp_hi:tp_lo = list of (column, row, attribute, string low, string high)
;   entries, ending with FF; the attribute is ORed into each character
;   (80 = inverse video)
; ---------------------------------------------------------------------------
#addr 0x3300
td_text_list:
    ld   ac, [SAVE_AC]          ; PUSH_LINK
    ld   [SP], x
    ld   [LINK_HI], ac
    ld   ac, [x]
    ld   [SP], ac
    dec
    ld   ac, x
    dec
    ld   ac, [SP]
    ld   [LINK_LO], ac
    ld   ac, [x]
    ld   [SAVE_AC], ac
td_tl_ent:
    ld   LINK_LO, x             ; CALL td_tbl_next: column, or FF
    ld   td_tl_1, [x]
    ld   LINK_HI, x
    ld   td_tl_1 >> 8, [x]
    ld   td_tbl_next >> 8, y
    jmp  td_tbl_next
td_tl_1:
    blt  td_tl_done
    ld   ac, [CUR_COL]
    ld   LINK_LO, x             ; CALL td_tbl_next: row
    ld   td_tl_2, [x]
    ld   LINK_HI, x
    ld   td_tl_2 >> 8, [x]
    ld   td_tbl_next >> 8, y
    jmp  td_tbl_next
td_tl_2:
    ld   ac, [CUR_ROW]
    ld   LINK_LO, x             ; CALL td_tbl_next: attribute
    ld   td_tl_3, [x]
    ld   LINK_HI, x
    ld   td_tl_3 >> 8, [x]
    ld   td_tbl_next >> 8, y
    jmp  td_tbl_next
td_tl_3:
    ld   ac, [s_attr]
    ld   LINK_LO, x             ; CALL td_tbl_next: string low
    ld   td_tl_4, [x]
    ld   LINK_HI, x
    ld   td_tl_4 >> 8, [x]
    ld   td_tbl_next >> 8, y
    jmp  td_tbl_next
td_tl_4:
    ld   ac, [R0]
    ld   LINK_LO, x             ; CALL td_tbl_next: string high
    ld   td_tl_5, [x]
    ld   LINK_HI, x
    ld   td_tl_5 >> 8, [x]
    ld   td_tbl_next >> 8, y
    jmp  td_tbl_next
td_tl_5:
    ld   ac, [R1]
    ld   LINK_LO, x             ; CALL td_put_str
    ld   td_tl_ent, [x]
    ld   LINK_HI, x
    ld   td_tl_ent >> 8, [x]
    ld   td_put_str >> 8, y
    jmp  td_put_str
td_tl_done:
    ld   lib_leave >> 8, y      ; LEAVE
    jmp  lib_leave

; ---------------------------------------------------------------------------
; td_put_str - print string R1:R0 (ending in 00) at the cursor, each
;   character ORed with s_attr
;   changes: AC, X, Y, R0, R1, T0-T5
; ---------------------------------------------------------------------------
#addr 0x3400
td_put_str:
    ld   ac, [SAVE_AC]          ; PUSH_LINK
    ld   [SP], x
    ld   [LINK_HI], ac
    ld   ac, [x]
    ld   [SP], ac
    dec
    ld   ac, x
    dec
    ld   ac, [SP]
    ld   [LINK_LO], ac
    ld   ac, [x]
    ld   [SAVE_AC], ac
td_ps_ch:
    ld   [R1], y
    ld   [R0], x
    ld   [y,x], ac
    beq  td_ps_done
    or   [s_attr], ac
    ld   LINK_LO, x             ; CALL con_putc
    ld   td_ps_1, [x]
    ld   LINK_HI, x
    ld   td_ps_1 >> 8, [x]
    ld   con_putc >> 8, y
    jmp  con_putc
td_ps_1:
    ld   [R0], ac
    inc
    ld   ac, [R0]
    bne  td_ps_ch
    ld   [R1], ac
    inc
    ld   ac, [R1]
    bra  td_ps_ch
td_ps_done:
    ld   lib_leave >> 8, y      ; LEAVE
    jmp  lib_leave

; ---------------------------------------------------------------------------
; td_put_range - print pr_n characters at the cursor, starting with AC,
;   adding pr_inc each time (0 repeats the character), each ORed with s_attr
;   changes: AC, X, Y, T0-T5, pr_c, pr_n
; ---------------------------------------------------------------------------
td_put_range:
    ld   ac, [SAVE_AC]          ; PUSH_LINK
    ld   [SP], x
    ld   [LINK_HI], ac
    ld   ac, [x]
    ld   [SP], ac
    dec
    ld   ac, x
    dec
    ld   ac, [SP]
    ld   [LINK_LO], ac
    ld   ac, [x]
    ld   [SAVE_AC], ac
    ld   ac, [pr_c]
td_pr_ch:
    ld   [pr_c], ac
    or   [s_attr], ac
    ld   LINK_LO, x             ; CALL con_putc
    ld   td_pr_1, [x]
    ld   LINK_HI, x
    ld   td_pr_1 >> 8, [x]
    ld   con_putc >> 8, y
    jmp  con_putc
td_pr_1:
    ld   [pr_c], ac
    add  [pr_inc], ac
    ld   ac, [pr_c]
    ld   [pr_n], ac
    dec
    ld   ac, [pr_n]
    bne  td_pr_ch
    ld   lib_leave >> 8, y      ; LEAVE
    jmp  lib_leave

; ---------------------------------------------------------------------------
; td_print_zp - print pz_n characters from the zero page, from R0 on
;   changes: AC, X, Y, R0, T0-T5, pz_n
; ---------------------------------------------------------------------------
#addr 0x3500
td_print_zp:
    ld   ac, [SAVE_AC]          ; PUSH_LINK
    ld   [SP], x
    ld   [LINK_HI], ac
    ld   ac, [x]
    ld   [SP], ac
    dec
    ld   ac, x
    dec
    ld   ac, [SP]
    ld   [LINK_LO], ac
    ld   ac, [x]
    ld   [SAVE_AC], ac
td_pz_ch:
    ld   [R0], x
    ld   [x], ac
    ld   LINK_LO, x             ; CALL con_putc
    ld   td_pz_1, [x]
    ld   LINK_HI, x
    ld   td_pz_1 >> 8, [x]
    ld   con_putc >> 8, y
    jmp  con_putc
td_pz_1:
    ld   [R0], ac
    inc
    ld   ac, [R0]
    ld   [pz_n], ac
    dec
    ld   ac, [pz_n]
    bne  td_pz_ch
    ld   lib_leave >> 8, y      ; LEAVE
    jmp  lib_leave

; ---------------------------------------------------------------------------
; td_tbl_next - AC = the byte at tp_hi:tp_lo, and move the pointer on
;   (a leaf routine; changes X, Y, tb_v)
; ---------------------------------------------------------------------------
td_tbl_next:
    ld   [tp_hi], y
    ld   [tp_lo], x
    ld   [y,x], ac
    ld   ac, [tb_v]
    ld   [tp_lo], ac
    inc
    ld   ac, [tp_lo]
    bne  td_tn_1
    ld   [tp_hi], ac
    inc
    ld   ac, [tp_hi]
td_tn_1:
    ld   [tb_v], ac
    ld   [LINK_HI], y           ; RETURN
    jmp  [LINK_LO]

; ===========================================================================
; text
; ===========================================================================
#addr 0x2000
; 80 column text: column, row, attribute, string
text_a:
    #d8 0, 0, 0x80, s_title & 0xFF, s_title >> 8
    #d8 17, 3, 0, s_fox & 0xFF, s_fox >> 8
    #d8 0, 6, 0, s_cpu & 0xFF, s_cpu >> 8
    #d8 30, 6, 0, s_up & 0xFF, s_up >> 8
    #d8 52, 6, 0, s_frm & 0xFF, s_frm >> 8
    #d8 0, 7, 0, s_ram & 0xFF, s_ram >> 8
    #d8 32, 7, 0, s_addr & 0xFF, s_addr >> 8
    #d8 42, 7, 0, s_pass & 0xFF, s_pass >> 8
    #d8 56, 7, 0, s_err & 0xFF, s_err >> 8
    #d8 0, 8, 0, s_prog & 0xFF, s_prog >> 8
    #d8 BAR_COL + NBAR, 8, 0, s_close & 0xFF, s_close >> 8
    #d8 0, 9, 0, s_area & 0xFF, s_area >> 8
    #d8 0, 10, 0, s_ruler & 0xFF, s_ruler >> 8
    #d8 0, 11, 0x80, s_legend & 0xFF, s_legend >> 8
    #d8 0xFF

s_title:
    #d " PLACARD COMPUTER  -  VIDEO TEST SCREEN                     80 COLUMNS  2-COLOR ", 0x00
s_fox:
    #d "The quick brown fox jumps over the lazy dog.  0123456789", 0x00
s_cpu:
    #d "CPU TEST    [ ]  RUNNING", 0x00
s_up:
    #d "UPTIME 00:00:00", 0x00
s_frm:
    #d "FRAME 00000", 0x00
s_ram:
    #d "RAM TEST", 0x00
s_addr:
    #d "PAGE 0100", 0x00
s_pass:
    #d "PASS 0", 0x00
s_err:
    #d "ERRORS 0", 0x00
s_area:
