; ===========================================================================
; td_tint_init - rows 0-95: mode byte = TINTB (1 bpp 1x, with their tint);
;   the raster bar starts at row 0
;   changes: AC, X, Y
; td_tint - move the raster bar: its old 20 rows get TINTB back, then the
;   bar (BARP) goes to row BARY[phase / 2]; called first thing in a frame,
;   in the vertical blanking.  About 1,600 clocks.
;   changes: AC, X, Y
; ===========================================================================
#addr 0x3060
td_tint_init:
    ld   95, ac
    ld   ac, [tn_i]
tti_l:
    ld   [tn_i], ac             ; mode byte x5A20 + row = TINTB[row]
    add  0x20, x                ; (TINTB is at xA220, the same low bytes)
    ld   TINTB >> 8, y
    ld   [y,x], ac
    ld   0x5A, y
    ld   ac, [y,x]
    ld   [tn_i], ac
    sub  1, ac
    ld   ac, [tn_i]
    bcc  tti_l
    ld   0x20, ac
    ld   ac, [tn_pos]
    clr  ac
    ld   ac, [tn_ph]
    ld   [LINK_HI], y           ; RETURN
    jmp  [LINK_LO]

td_tint:
    ld   TN_N - 1, ac         ; the rows the bar covered: TINTB again
    ld   ac, [tn_i]
tt_r:
    ld   [tn_i], ac
    add  [tn_pos], x
    ld   TINTB >> 8, y
    ld   [y,x], ac
    ld   0x5A, y
    ld   ac, [y,x]
    ld   [tn_i], ac
    sub  1, ac
    ld   ac, [tn_i]
    bcc  tt_r
    ld   [tn_ph], ac            ; next place: BARY[phase / 2] + x20
    add  1, ac
    and  0x7F, ac
    ld   ac, [tn_ph]
    shr  ac
    add  BARY & 0xFF, x
    ld   BARY >> 8, y
    ld   [y,x], ac
    add  0x20, ac
    ld   ac, [tn_pos]
    ld   TN_N - 1, ac         ; the bar
    ld   ac, [tn_i]
tt_b:
    ld   [tn_i], ac
    add  BARP & 0xFF, x
    ld   BARP >> 8, y
    ld   [y,x], ac
    ld   ac, [tn_v]
    ld   [tn_i], ac
    add  [tn_pos], x
    ld   0x5A, y
    ld   [tn_v], ac
    ld   ac, [y,x]
    ld   [tn_i], ac
    sub  1, ac
    ld   ac, [tn_i]
    bcc  tt_b
    ld   [LINK_HI], y           ; RETURN
    jmp  [LINK_LO]

; ===========================================================================
; raster bar tables (xA220-xA2FF, after the scroller's page tables)
; ===========================================================================
#addr 0x0B20
TINTB:                          ; tint of rows 0-95 (x20 + row): a blue panel
    #d8 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
    #d8 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
    #d8 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x40, 0x40, 0x40, 0x40
    #d8 0x40, 0x40, 0x40, 0x40, 0x40, 0x40, 0x40, 0x40, 0x40, 0x40, 0x40, 0x40, 0x40, 0x40, 0x40, 0x40
    #d8 0x40, 0x40, 0x40, 0x40, 0x40, 0x40, 0x40, 0x40, 0x40, 0x40, 0x40, 0x40, 0x40, 0x40, 0x40, 0x40
    #d8 0x40, 0x40, 0x40, 0x40, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
#addr 0x0B80                    ;   behind the status lines, rows 44-83
BARP:                           ; the bar, 20 rows: blue, magenta, red, gold,
    #d8 0x40, 0x40, 0x50, 0x50, 0x10, 0x10, 0x30, 0x30, 0x70, 0x70, 0x70, 0x70, 0x30, 0x30, 0x10, 0x10
    #d8 0x50, 0x50, 0x40, 0x40
#addr 0x0BA0                    ;   grey (all three), and back
BARY:                           ; its first row, 64 steps of a bounce, 0-76
    #d8 0x00, 0x00, 0x01, 0x02, 0x03, 0x04, 0x06, 0x09, 0x0B, 0x0E, 0x11, 0x14, 0x17, 0x1B, 0x1F, 0x22
    #d8 0x26, 0x2A, 0x2D, 0x31, 0x35, 0x38, 0x3B, 0x3E, 0x41, 0x43, 0x46, 0x48, 0x49, 0x4A, 0x4B, 0x4C
    #d8 0x4C, 0x4C, 0x4B, 0x4A, 0x49, 0x48, 0x46, 0x43, 0x41, 0x3E, 0x3B, 0x38, 0x35, 0x31, 0x2D, 0x2A
    #d8 0x26, 0x22, 0x1F, 0x1B, 0x17, 0x14, 0x11, 0x0E, 0x0B, 0x09, 0x06, 0x04, 0x03, 0x02, 0x01, 0x00

; ===========================================================================
; small tables (one page, TBL)
; ===========================================================================
#addr TBL
SPIN:                           ; text spinner | / - \
    #d8 0x7C, 0x2F, 0x2D, 0x5C
#addr TBL + 0x08
TAIL:                           ; wheel: white head, yellow, bright red,
    #d8 0xFF, 0xEE, 0xCC, 0x44, 0x88, 0x88, 0x88, 0x88  ; red, dark gray
#addr TBL + 0x10
DOTC:                           ; wheel dot byte columns, clockwise from 3:00
    #d8 74, 73, 69, 65, 64, 65, 69, 73
#addr TBL + 0x18
DOTR:                           ; wheel dot rows, 96 + 4 * block row
    #d8 96 + 4 * 14, 96 + 4 * 21, 96 + 4 * 24, 96 + 4 * 21
    #d8 96 + 4 * 14, 96 + 4 * 7, 96 + 4 * 4, 96 + 4 * 7
#addr TBL + CLK
CLKLIM:                         ; uptime digit limits: h h : m m : s s
    #d8 0x3A, 0x3A, 0x36, 0x3A, 0x36, 0x3A
#addr TBL + 0x40
RAINBOW:                        ; "16 COLORS"
    #d8 0xCC, 0xEE, 0x00, 0xAA, 0xBB, 0x99, 0xDD, 0xCC, 0xEE
#addr TBL + 0x90
PAT_P:                          ; RAM test patterns: 0-11 fixed values,
                                ;   12-13 XOR the address
    #d8 0x00, 0xFF, 0x55, 0xAA, 0x01, 0x02, 0x04, 0x08
    #d8 0x10, 0x20, 0x40, 0x80, 0x00, 0xFF
#addr TBL2
PAGES:                          ; RAM test pages: x01-x1E, x20-x4F, x54-x59,
    #d8 0x3B, 0x3C, 0x3D, 0x3E, 0x3F, 0x40, 0x41, 0x42
    #d8 0x43, 0x44, 0x45, 0x46, 0x47, 0x48, 0x49, 0x4A
    #d8 0x4B, 0x4C, 0x54, 0x55, 0x56, 0x57, 0x58, 0x59
    #d8 0x5C
#addr TBL2 + 0x60               ;   x5C
DIGITS:                         ; the 256 band
    #d "256"
#addr TBL2 + 0x68
SHADES:                         ; font rows 0-6 of each digit: reds, blues,
    #d8 0x07, 0x06, 0x05, 0x04, 0x03, 0x02, 0x01, 0x00  ; greens, bright
    #d8 0x18, 0x18, 0x18, 0x10, 0x10, 0x08, 0x08, 0x00  ; at the top
    #d8 0xE0, 0xC0, 0xA0, 0x80, 0x60, 0x40, 0x20, 0x00

